import type { ReleaseCourse, ReleaseTask } from './a13-release';

export type ReleasePracticeQuestion = {
  id: string;
  version: number;
  targetId: string;
  topicId: string;
  subskill: string;
  kind: 'choice' | 'cloze' | 'order';
  acceptedAnswers: string[];
};

/** This projection must match the server catalog generated by build-a13-release.py. */
export function releasePracticeQuestion(
  course: Pick<ReleaseCourse, 'lessonId' | 'skill'>,
  task: ReleaseTask,
): ReleasePracticeQuestion {
  return {
    id: task.id,
    version: task.version,
    targetId: task.targetId,
    topicId: `${course.lessonId}-${course.skill}`,
    subskill: task.subskill,
    kind: task.kind === 'write' ? 'cloze' : task.kind,
    acceptedAnswers: task.acceptedAnswers,
  };
}
